                return (0, 0, c)
            return ((p[1] - dp[1]), (p[0] - dp[0]), c)
        customer_ids.sort(key=angle_key)
    else:
        customer_ids.sort(key=lambda c: (-demand_of(c), c))

    unassigned = customer_ids[:]
    routes = []

    while unassigned:
        best = None
        best_score = None
        for c in unassigned:
            if feasible_add(0, c):
                score = (dist(depot, c), -demand_of(c), c)
                if best is None or score < best_score:
                    best = c
                    best_score = score
        if best is None:
            best = unassigned[0]

        route = [best]
        load = demand_of(best)
        unassigned.remove(best)
        current = best

        while True:
            cand = None
            cand_score = None
            for c in unassigned:
                if feasible_add(load, c):
                    score = (dist(current, c), dist(depot, c), c)
                    if cand is None or score < cand_score:
                        cand = c
                        cand_score = score
            if cand is None:
                break
            route.append(cand)
            load += demand_of(cand)
            unassigned.remove(cand)
            current = cand

        routes.append(route)

    # local search: deterministic 2-opt per route
    for r in range(len(routes)):
        route = routes[r]
        n = len(route)
        if n < 4:
            continue
        improved = True
        while improved:
            improved = False
            best_delta = 0
            bi = bj = -1
            for i in range(n - 2):
                a = depot if i == 0 else route[i - 1]
                b = route[i]
                for j in range(i + 2, n):
                    c = route[j]
                    d = depot if j == n - 1 else route[j + 1]
                    delta = (dist(a, c) + dist(b, d)) - (dist(a, b) + dist(c, d))
                    if delta < best_delta:
                        best_delta = delta
                        bi = i
                        bj = j
            if bi >= 0:
                route[bi:bj + 1] = route[bi:bj + 1][::-1]
                improved = True
        routes[r] = route

    # simple cross-route repair by relocating single customers if it reduces total cost
    changed = True
    while changed:
        changed = False
        best_move = None
        best_gain = 0
        for i in range(len(routes)):
            ri = routes[i]
            for p in range(len(ri)):
                c = ri[p]
                dem = demand_of(c)
                for j in range(len(routes)):
                    if i == j:
                        continue
                    rj = routes[j]
                    loadj = 0
                    for x in rj:
                        loadj += demand_of(x)
                    if capacity and capacity > 0 and loadj + dem > capacity:
                        continue
                    before_i = route_cost(ri)
                    before_j = route_cost(rj)
                    rem_i = ri[:p] + ri[p + 1:]
                    if len(rem_i) == 0:
                        continue
                    for ins in range(len(rj) + 1):
                        new_j = rj[:ins] + [c] + rj[ins:]
                        gain = (before_i + before_j) - (route_cost(rem_i) + route_cost(new_j))
                        if gain > best_gain:
                            best_gain = gain
                            best_move = (i, j, p, ins)
        if best_move is not None:
            i, j, p, ins = best_move
            c = routes[i][p]
            routes[i] = routes[i][:p] + routes[i][p + 1:]
            routes[j] = routes[j][:ins] + [c] + routes[j][ins:]
            if len(routes[i]) == 0:
                routes[i] = []
            changed = True
            routes = [rt for rt in routes if rt]

    return routes
